ecific terms and topics:"}, {"id": "d1035921-4f86-49e9-8d8a-2061b4604c46", "type": "concept", "title": "Aemilia Lanyer"}, {"id": "e3772b20-87cd-4c66-8d68-ad8a6de5c3f3", "type": "concept", "title": "Mary Wroth"}, {"id": "d1bd49bc-ccbf-4cf2-adcf-555bfcb09486", "type": "concept", "title": "Elizabeth Cary"}, {"id": "ca114a11-2684-40ca-a8de-01d5032c69dc", "type": "concept", "title": "Margaret Cavendish"}, {"id": "175b1009-4af1-4275-bdcc-42b610cf2d59", "type": "concept", "title": "dedication"}, {"id": "f92bdf1f-5c7a-4648-bc6c-01f18b09e1ff", "type": "concept", "title": "modesty topos"}, {"id": "ab7c3466-45f6-466b-8da3-ae05d39668a7", "type": "concept", "title": "patronage"}, {"id": "38a7bba4-9eec-44f7-9cfb-a8f4adf719c6", "type": "concept", "title": "coterie"}], "description": "Students learn the constraints and strategies of women writing in manuscript and print."}, {"id": "79603373-11e8-4a3c-9cee-7bc8943688e3", "type": "subtopic", "title": "Marriage, chastity, and domestic authority", "children": [{"id": "8ed8a732-ed41-4112-9051-43fffcd002ac", "type": "concept", "title": "Specific terms and topics:"}, {"id": "54391fde-75ae-42a6-95e7-4bc43d63becd", "type": "concept", "title": "coverture"}, {"id": "48bf1c3d-dca6-4f4a-8ea5-2cc4b2f7558a", "type": "concept", "title": "dowry"}, {"id": "c1347557-083a-4b25-a6a8-415a7f612bc2", "type": "concept", "title": "obedience"}, {"id": "ba47ac44-2e03-43c1-b4d8-19ef95fe96d8", "type": "concept", "title": "chastity"}, {"id": "70ddb0b9-cdd9-4789-b2ac-8ba1ca76ca46", "type": "concept", "title": "widowhood"}, {"id": "394dc09b-6373-4232-bf7f-8a95431b64d1", "type": "concept", "title": "household government"}, {"id": "74a91342-f950-4fb3-b8fa-4a3f5c27eb77", "type": "concept", "title": "conduct book"}, {"id": "2ed8452c-4046-4c0a-bcf8-d1adc4959286", "type": "concept", "title": "patriarchy"}], "description": "The gist is to connect literary plots with the social organization of household power."}, {"id": "ef3e14c3-b369-4cef-80f1-cc1f08fd0b15", "type": "subtopic", "title": "Gendered voice and revision", "children": [{"id": "66e852e9-d127-4678-b74b-b765d3851abe", "type": "concept", "title": "Specific terms and topics:"}, {"id": "84c2fc05-fab0-46d1-a75e-43ae6b4f6c72", "type": "concept", "title": "Eve apology"}, {"id": "45ea34ed-08d9-4293-be1b-a4521b1c91b5", "type": "concept", "title": "Salve Deus Rex Judaeorum"}, {"id": "1a94e3e3-93d5-4bec-9679-399085b0b6b5", "type": "concept", "title": "Pamphilia"}, {"id": "5cf377ec-4788-4d43-a80c-6d892fd5cd39", "type": "concept", "title": "Mariam"}, {"id": "1ed1c7ec-2de7-4bf1-b7da-69b60e946416", "type": "concept", "title": "female complaint"}, {"id": "51736324-d8d5-4f02-91c5-e1d902faef15", "type": "concept", "title": "prophecy"}, {"id": "af76fe0b-e8cb-4dee-bb7d-ca9addfb8315", "type": "concept", "title": "counter-blazon"}, {"id": "941951c4-dc35-4419-a105-efd05e187521", "type": "concept", "title": "authorial self-defense"}], "description": "Students examine how women writers revise scripture, romance, sonnet convention, and political speech."}]}, {"id": "1bb7acea-6a88-43e3-9653-decc7dd8f78b", "type": "topic", "title": "Race, Empire, Travel, and Encounter", "description": "Early modern texts register expanding contact with Africa, the Americas, Ireland, the Ottoman world, and Asia. Students learn the vocabulary and violence of early imperial imagination.", "children": [{"id": "6d26616f-cb9a-4fea-9bac-d0c1caa3328c", "type": "subtopic", "title": "Travel writing and colonial discourse", "children": [{"id": "4977bf06-eaad-428d-9ef0-6d6fc4abb9b0", "type": "concept", "title": "Specific terms and topics:"}, {"id": "2493a6b5-be94-49aa-9499-78ac9fc382ff", "type": "concept", "title": "Richard Hakluyt"}, {"id": "34edbce1-e331-4270-96f8-15d0a1906582", "type": "concept", "title": "New World"}, {"id": "b18d303f-c0ca-446e-bd5f-ad7f5e77b4aa", "type": "concept", "title": "Virginia"}, {"id": "bf3e7d74-242f-4637-9f51-0a32a679b420", "type": "concept", "title": "plantation"}, {"id": "b07d4da9-6d98-4fe2-94de-