tice", "children": [{"id": "8727fe1a-56c1-4cca-b150-26b0b7a9baf2", "type": "concept", "title": "Specific terms and topics:"}, {"id": "d66a77f8-fee7-433d-b9eb-de8e43cfeead", "type": "concept", "title": "Globe"}, {"id": "b2b31379-4bf9-428b-9e0b-074334e7f8b1", "type": "concept", "title": "Blackfriars"}, {"id": "6def6ac2-21e0-4c38-b4ae-0f832eb7244b", "type": "concept", "title": "thrust stage"}, {"id": "22794bd7-c083-472a-ac5b-9ec26902f70b", "type": "concept", "title": "discovery space"}, {"id": "2ffe972f-0fe9-45f6-8e5d-9278ed75f473", "type": "concept", "title": "groundlings"}, {"id": "0eed6225-93d3-469d-9f32-f14622ec0b0a", "type": "concept", "title": "boy actors"}, {"id": "832cac7d-e5ff-46a4-88e0-70e34bc7c13d", "type": "concept", "title": "doubling"}, {"id": "b29f2c22-aa42-433f-b468-26b7afd5642c", "type": "concept", "title": "props"}], "description": "Students learn how material stage conditions shape interpretation."}, {"id": "a69e062b-789f-4630-ac48-3c39d7eacf91", "type": "subtopic", "title": "Textual transmission and scholarly editions", "children": [{"id": "a6f951bc-7edb-43b9-abee-0a3a119c13f7", "type": "concept", "title": "Specific terms and topics:"}, {"id": "b26e67a0-4dd9-473f-839c-1d1cfc92d237", "type": "concept", "title": "quarto"}, {"id": "1d6bcb90-ba8c-468b-a0d0-aed27b758d0e", "type": "concept", "title": "folio"}, {"id": "075d6731-a9e0-49f8-9e3b-59d02e70f064", "type": "concept", "title": "bad quarto"}, {"id": "35d3e8d9-e589-43a4-bccc-a48ce93afa1c", "type": "concept", "title": "variant"}, {"id": "7a1eddd8-bc0e-4518-9fad-cb86d42c0497", "type": "concept", "title": "modernization"}, {"id": "557912e0-8a76-476e-be50-ab6bbb74cd97", "type": "concept", "title": "collation"}, {"id": "17bcad55-a804-49cb-a56e-3690ffcb3018", "type": "concept", "title": "apparatus"}, {"id": "3495d230-bb68-424d-ae37-a207fa7e174a", "type": "concept", "title": "editorial emendation"}], "description": "The gist is to understand why early modern texts are unstable and how editors make choices."