update public.learning_paths
set
  title = 'Renaissance / Early Modern Literature',
  goal = 'Renaissance / Early Modern Literature',
  summary = 'Renaissance / Early Modern Literature studies English writing from roughly the late 15th through the 17th century, with attention to humanism, Reformation conflict, lyric poetry, drama, prose, women writers, empire, print culture, political theology, and Milton. Students read major authors such as Sidney, Spenser, Marlowe, Shakespeare, Donne, Lanyer, Wroth, Jonson, Webster, and Milton while also learning how books, theaters, courts, churches, households, and colonial encounters shaped literary form.',
  data = $renljson${"slug": "renaissance-early-modern-literature", "title": "Renaissance / Early Modern Literature", "description": "Renaissance / Early Modern Literature studies English writing from roughly the late 15th through the 17th century, with attention to humanism, Reformation conflict, lyric poetry, drama, prose, women writers, empire, print culture, political theology, and Milton. Students read major authors such as Sidney, Spenser, Marlowe, Shakespeare, Donne, Lanyer, Wroth, Jonson, Webster, and Milton while also learning how books, theaters, courts, churches, households, and colonial encounters shaped literary form.", "topics": [{"id": "5adddc50-5fbe-4789-9a0e-bcabb1b9e7af", "type": "topic", "title": "Renaissance Humanism and the English Renaissance", "description": "This section establishes the intellectual world that made early modern literature possible: classical recovery, rhetorical training, translation, and new claims for poetry's civic and moral value.", "children": [{"id": "6f3cb935-b20c-4cfe-8e6f-b8b899402342", "type": "subtopic", "title": "Classical revival and studia humanitatis", "children": [{"id": "475f72f8-31fe-4871-92d3-2e74277d80a4", "type": "concept", "title": "Specific terms and topics:"}, {"id": "3a81ff54-4ff3-4ae5-aa74-f2d415e8aa7b", "type": "concept", "title": "Cicero"}, {"id": "ca423c78-3ff6-4990-9c2b-d21db7ab4f39", "type": "concept", "title": "Quintilian"}, {"id": "a29f2c1e-6ce5-4771-8c97-000721d90cd1", "type": "concept", "title": "Seneca"}, {"id": "2f781108-8324-462d-b562-9bd8eb58a0e1", "type": "concept", "title": "Ovid"}, {"id": "795c51b4-e7de-492b-9d38-f0aeb7266d21", "type": "concept", "title": "Virgil"}, {"id": "f62d7f10-c4f8-4b5f-b9ce-bff1165d18f3", "type": "concept", "title": "imitation"}, {"id": "3e95eeca-5b1f-480c-89a8-b7a4a56491a8", "type": "concept", "title": "translation"}, {"id": "4bcd433a-3a70-470e-a048-a9cf3ed771cf", "type": "concept", "title": "grammar-school curriculum"}], "description": "Students learn why Latin and Greek models shaped English literary form, authorship, and educational ideals."}, {"id": "1e5da821-2075-4cf8-a8e6-72731440d30b", "type": "subtopic", "title": "English Renaissance identity", "children": [{"id": "a400b072-f204-4fff-a42c-84d59c5ad579", "type": "concept", "title": "Specific terms and topics:"}, {"id": "b5afe911-bd36-4252-bcbe-51cab4fa0b88", "type": "concept", "title": "Tudor monarchy"}, {"id": "81aade6a-3bda-4159-97ab-315c557d1557", "type": "concept", "title": "vernacularization"}, {"id": "0cc4470f-cf58-44a1-823b-128a0ec6987e", "type": "concept", "title": "courtly authorship"}, {"id": "6c81160c-46fd-459a-ba43-ca88ee09a85d", "type": "concept", "title": "patronage"}, {"id": "17a97ee0-b89d-4694-b97c-dd9b5daad0f5", "type": "concept", "title": "Elizabethan settlement"}, {"id": "a4e16210-3cd3-4606-9569-b0c8c96a0e03", "type": "concept", "title": "national mythmaking"}], "description": "The point is to connect national literary ambition with court politics, print expansion, and vernacular prestige."}, {"id": "eb77dff1-d94f-44b9-9226-2c3ac919dc20", "type": "subtopic", "title": "Rhetoric and invention", "children": [{"id": "148ef97c-e527-42a9-aef6-a1c309bd9bc7", "type": "concept", "title": "Specific terms and topics:"}, {"id": "9362ade3-dde6-4b6c-9ba6-4eed69efaf9e", "type": "concept", "title": "inventio"}, {"id": "5bd1172c-3c59-47cc-8531-3c19e22fbd1e", "type": "concept", "title": "dispositio"}, {"id": "aa3fae9a-b0d0-49ca-a201-2f732e3d7f6e", "type": "concept", "title": "elocutio"}, {"id": "472e2553-fd05-4703-96f3-328898a9c0c0", "type": "concept", "title": "amplification"}, {"id": "05df58f2-a063-4d50-948b-8e3637de4b30", "type": "concept", "title": "figures of speech"}, {"id": "92e74c8b-8504-48b6-b496-449f0c3a0a85", "type": "concept", "title": "commonplaces"}, {"id": "c6adfb29-1b56-4527-83fc-7830ce0c8f9c", "type": "concept", "title": "oration"}, {"id": "6bfd60cf-d91d-4c8b-911a-d1cba9dd996e", "type": "concept", "title": "declamation"}], "description": "Rhetoric gives students the toolkit for seeing how early modern writers build persuasion, style, and argument."}]}, {"id": "5aa1ded1-c656-4bff-9524-d6144b28651e", "type": "topic", "title": "Reformation, Religion, and Early Modern Belief", "description": "Early modern literature is inseparable from religious upheaval. This section shows how theology, worship, conscience, and censorship shaped literary language.", "children": [{"id": "927407fa-97fa-40de-a99e-cabfae6a7b1a", "type": "subtopic", "title": "Reformation conflict and confessional culture", "children": [{"id": "0fa9dac0-85b2-41f8-8eb5-329b9b133a34", "type": "concept", "title": "Specific terms and topics:"}, {"id": "fbb7042c-7dd8-4e4b-99a7-b610cb54e0b5", "type": "concept", "title": "Protestantism"}, {"id": "a409f1f2-9180-410a-979c-a352f032605c", "type": "concept", "title": "Catholic recusancy"}, {"id": "c1e1e62a-ef51-42c1-91c1-5200c2b5226d", "type": "concept", "title": "Anglican settlement"}, {"id": "5d3a383a-a0a1-4e64-9699-5e7490240048", "type": "concept", "title": "iconoclasm"}, {"id": "00dcb61c-c07c-44c1-9892-ae07b6a61d73", "type": "concept", "title": "martyrdom"}, {"id": "a2d198f3-c733-4c8c-8e49-b1c2427e24fe", "type": "concept", "title": "Foxe's Acts and Monuments"}, {"id": "a9a8b045-a6a1-4382-80e3-151df7ce4f51", "type": "concept", "title": "Thirty-Nine Articles"}], "description": "Students learn how religious change produced new genres of polemic, devotion, and identity formation."}, {"id": "193a1b44-8919-4384-9120-d0bb7efa3176", "type": "subtopic", "title": "Biblical translation and devotional language", "children": [{"id": "39491896-626b-4e48-80c4-26c374e49b76", "type": "concept", "title": "Specific terms and topics:"}, {"id": "0b5417f7-112c-465c-a9ed-ef0888c4ac05", "type": "concept", "title": "Tyndale Bible"}, {"id": "f0c03006-e846-4de1-bf09-0fdc3c342f30", "type": "concept", "title": "Geneva Bible"}, {"id": "aa74e8b5-008a-4ff3-9d19-f4390152e7b8", "type": "concept", "title": "King James Bible"}, {"id": "cf0be54